code='''from collections import deque

def transform(grid):
    # Replace background cells enclosed by the non-background outline with 4.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or c == 0 or r == h-1 or c == w-1) and grid[r][c] == bg:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in seen:
                out[r][c]=4
    return out
'''
